int n;
cin >> n;                    // size known only now
int *a = new int[n];         // n boxes on the heap, values not set

for (int i = 0; i < n; i++)
    cin >> a[i];             // use like a normal array

delete[] a;                  // free the whole array (brackets!)
a = nullptr;

int *z = new int[n]();       // all elements start at 0

// 2-D variation (array of pointers)
int **g = new int*[rows];
for (int r = 0; r < rows; r++) g[r] = new int[cols];
// free: delete[] g[r] for every row, then delete[] g;

sample.code:
#include <iostream>
using namespace std;

int main() {
    int n;
    cout << "How many marks? ";
    cin >> n;

    int *marks = new int[n];
    for (int i = 0; i < n; i++) {
        cin >> marks[i];
    }

    int sum = 0;
    for (int i = 0; i < n; i++) {
        sum = sum + marks[i];
    }
    cout << "Sum = " << sum << endl;

    delete[] marks;
    marks = nullptr;
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    int n;
    cin >> n;

    int *sq = new int[n];
    for (int i = 0; i < n; i++) {
        sq[i] = (i + 1) * (i + 1);
    }

    for (int i = 0; i < n; i++) {
        cout << *(sq + i);
        if (i < n - 1) {
            cout << " ";
        }
    }
    cout << endl;

    int big = sq[0];
    for (int i = 1; i < n; i++) {
        if (sq[i] > big) {
            big = sq[i];
        }
    }
    cout << "Largest = " << big << endl;

    delete[] sq;
    sq = nullptr;
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    int size = 3;
    int *a = new int[size];
    for (int i = 0; i < size; i++) {
        a[i] = (i + 1) * 10;
    }

    int *bigger = new int[size * 2];
    for (int i = 0; i < size; i++) {
        bigger[i] = a[i];
    }
    delete[] a;
    a = bigger;
    bigger = nullptr;
    size = size * 2;

    for (int i = 3; i < size; i++) {
        a[i] = (i + 1) * 10;
    }

    cout << "Size = " << size << endl;
    for (int i = 0; i < size; i++) {
        cout << "a[" << i << "] = " << a[i] << endl;
    }

    delete[] a;
    a = nullptr;
    return 0;
}

